import{_ as a,o as e,c as r,ag as o}from"./chunks/framework.DMXcdKmJ.js";const c=JSON.parse('{"title":"管理应用开发数据点","description":"在应用开发中查找数据点、复制路径，并为工程角色配置调用权限，与数据中心点位配置分工。","frontmatter":{"title":"管理应用开发数据点","description":"在应用开发中查找数据点、复制路径，并为工程角色配置调用权限，与数据中心点位配置分工。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/workspace-datapoints.md","filePath":"zh/使用指南/管理应用开发数据点.md"}'),i={name:"zh/guide/workspace-datapoints.md"};function d(l,t,n,h,s,p){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="管理应用开发数据点" tabindex="-1">管理应用开发数据点 <a class="header-anchor" href="#管理应用开发数据点" aria-label="Permalink to &quot;管理应用开发数据点&quot;">​</a></h1><p>本页的入口是 <strong>“应用开发” → “数据点”</strong>，主要供页面开发时查找点位、读取详情和配置工程角色的调用权限。</p><p>它不是数据中心的点位来源编辑器。需要创建查询、采集变量或计算输出时，先去<a href="/induframe-docs/zh/guide/datacenter.html">数据中心</a>的对应来源配置。</p><h2 id="_1-查找并复制路径" tabindex="-1">1. 查找并复制路径 <a class="header-anchor" href="#_1-查找并复制路径" aria-label="Permalink to &quot;1. 查找并复制路径&quot;">​</a></h2><ol><li>打开目标工程的“应用开发”，选择 <strong>“数据点”</strong>。</li><li>使用“搜索名称或路径”及来源、类型、状态筛选查找。</li><li>点击数据点名称查看详情，核对路径、来源、类型和异常原因。</li><li>点击该行 <strong>“复制”</strong>，粘贴后确认完整路径。</li></ol><p>来源多时，可使用“搜索来源”与“更多来源”。没有结果时先使用“清除筛选”或“刷新”，并核对是否在正确工程，不直接新建一批同名配置。</p><p>路径不是授权凭据。复制给其他用户或让 AI 使用，不会自动赋予调用权限。</p><h2 id="_2-准备工程角色" tabindex="-1">2. 准备工程角色 <a class="header-anchor" href="#_2-准备工程角色" aria-label="Permalink to &quot;2. 准备工程角色&quot;">​</a></h2><p>调用权限分配给<strong>工程角色</strong>，再由工程用户绑定角色。角色还不存在时，先到“工程管理”中的“用户预设”创建，见<a href="/induframe-docs/zh/guide/project-roles.html">管理工程角色</a>。</p><p>组织的“工程人员”“运维人员”等角色不是这里要勾选的工程角色。</p><h2 id="_3-为一个点或一批点配置调用权限" tabindex="-1">3. 为一个点或一批点配置调用权限 <a class="header-anchor" href="#_3-为一个点或一批点配置调用权限" aria-label="Permalink to &quot;3. 为一个点或一批点配置调用权限&quot;">​</a></h2><ol><li>单点操作时打开详情，点击 <strong>“调用权限”</strong>；批量操作时先勾选数据点，再点击选择条的同名按钮。</li><li>核对已选数量。跨页操作可能保留此前选择，不只看当前页；需要重新开始时使用“清除选择”。</li><li>在对话框中找到目标工程角色。</li><li>勾选表示允许该角色调用本次选择的点；取消勾选表示撤销。</li><li>点击 <strong>“保存”</strong>，等待结果，再重新打开核对。</li></ol><p>半选状态表示本次选中的点只有一部分已授权，不等于全部允许或全部禁止。不要为了消除半选图标直接反复点击，先确认期望的授权范围。</p><p>内置角色和“全部数据点”角色不可在此编辑。界面读取角色失败或保存失败时先保留提示，重新核对，不假定所有角色都已成功更新。</p><h2 id="_4-用合适身份确认" tabindex="-1">4. 用合适身份确认 <a class="header-anchor" href="#_4-用合适身份确认" aria-label="Permalink to &quot;4. 用合适身份确认&quot;">​</a></h2><p>在<a href="/induframe-docs/zh/guide/preview.html">页面预览</a>使用相应工程用户，核对页面能够调用需要的数据，且没有多余访问。仅看编辑器或开发人员自己的画面不能证明普通工程用户的权限正确。</p><p>这些修改属于工程开发配置，正式运行仍需按发布、更新安排同步并单独验证。</p><h2 id="与数据中心怎样分工" tabindex="-1">与数据中心怎样分工 <a class="header-anchor" href="#与数据中心怎样分工" aria-label="Permalink to &quot;与数据中心怎样分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>主要任务</th></tr></thead><tbody><tr><td>应用开发 → 数据点</td><td>页面开发选点、复制路径、工程角色调用权限</td></tr><tr><td>数据中心 → 数据点</td><td>查看来源与开发态当前值、标签、历史与报警关联、失效项</td></tr><tr><td>数据中心 → 对应来源</td><td>创建或修改查询、工业变量、计算输出等实际配置</td></tr></tbody></table><p>下一步：<a href="/induframe-docs/zh/guide/datapoints.html">数据中心的数据点列表</a> · <a href="/induframe-docs/zh/guide/project-users.html">管理工程用户</a>。</p>',20)])])}const u=a(i,[["render",d]]);export{c as __pageData,u as default};
